import json
from collections import Counter, defaultdict
from pathlib import Path
ROOT = Path("/tmp/opensip-design-corrections/consumer-b.v12-team-corrections.v2")
rev = json.loads((ROOT/"team-inputs/kit-scope-review-v2/review.json").read_text())
print("dispositionCounts", json.dumps(rev["dispositionCounts"], indent=2))
print("\n=== MUST ===")
for m in rev["newMustIssues"]:
    print(m["id"], m.get("requirementIds"), m.get("finding","")[:200])
print("\n=== SHOULD ===")
for m in rev["newShouldIssues"]:
    print(m["id"], m.get("requirementIds"), m.get("finding","")[:200])
print("\n=== WITHDRAWN ===")
for w in rev.get("withdrawnFromV1") or []:
    if isinstance(w, dict):
        print(w.get("id"), w.get("finding","")[:160] if isinstance(w.get("finding"), str) else list(w.keys())[:8])
    else:
        print(w)
print("\n=== ASSESSED BY DISPOSITION ===")
by=defaultdict(list)
for r in rev["assessed"]:
    by[r["disposition"]].append(r)
for d, rows in by.items():
    print(f"\n## {d} ({len(rows)})")
    for r in rows:
        print(f"  {r['id']:40} kind={r.get('kind')} own={str(r.get('owningRecord'))[:80]} meas={r.get('measurementKind')}")
PY
", "description": "Extract 134-row dispositions and MUST/SHOULD issues"}

