{"command": "/tmp/opensip-architecture-review-env/bin/python -I -B - <<'PY'
import json
from pathlib import Path
KIT = Path("/tmp/opensip-design-corrections/consumer-b.v12-team-corrections.v2/subject")

def load(rel):
    return json.loads((KIT/rel).read_text())

def show(d, name, depth=0):
    print(f"{'  '*depth}{name} required={d.get('required')} addl={d.get('additionalProperties')}")
    props=d.get("properties") or {}
    for k,v in props.items():
        req = '*' if k in (d.get('required') or []) else ' '
        if "$ref" in v:
            print(f"{'  '*depth} {req} {k}: $ref {v['$ref']}")
        elif v.get("type")=="object":
            print(f"{'  '*depth} {req} {k}: object req={v.get('required')} keys={list(v.get('properties',{}) )[:12]}")
        elif v.get("type")=="array":
            items=v.get("items") or {}
            print(f"{'  '*depth} {req} {k}: array items.ref={items.get('$ref')} items.type={items.get('type')} min={v.get('minItems')} max={v.get('maxItems')} order={v.get('x-opensip-order')}")
        else:
            print(f"{'  '*depth} {req} {k}: type={v.get('type')} enum={v.get('enum')} const={v.get('const')} pattern={str(v.get('pattern'))[:60]}")

gq=load("docs/coop/design-corrections/workflows/schemas/evaluator3/graph-query.schema.json")
for n in ["GraphQueryRequestV1","GraphQueryResponseV1","GraphNeighborsParams","GraphPathParams","GraphReachParams","View","GraphEndpoint","Page","Bounds","GraphEvidenceDisclosure","GraphNeighborRow"]:
    print("\n====", n)
    show(gq["$defs"][n])

native=load("docs/coop/design-corrections/native/native-evidence.schemas.v2.json")
print("\n==== TypeScriptConfigGraphV1")
show(native["$defs"]["TypeScriptConfigGraphV1"])
if "TypeScriptConfigGraphNodeV1" in native["$defs"]:
    show(native["$defs"]["TypeScriptConfigGraphNodeV1"])
# search config graph node
for k in native["$defs"]:
    if "Config" in k or "tsconfig" in k.lower() or "GraphNode" in k:
        if k not in ("TypeScriptConfigGraphV1",):
            print(" def", k, "req", native["$defs"][k].get("required"))

inv=load("docs/coop/design-corrections/workflows/schemas/evaluator3/invocation-record.schema.json")
print("\n==== StepSpec")
show(inv["$defs"]["StepSpec"])
print("\n==== WorkflowRef")
show(inv["$defs"]["WorkflowRef"])
print("Mode", inv["$defs"]["Mode"])
print("StepKind", inv["$defs"]["StepKind"])

# errors array items for command envelope
ce=load("docs/coop/design-corrections/workflows/schemas/evaluator3/command-envelope.schema.json")
print("\nerrors items", ce["properties"]["errors"].get("items"))
print("exitCode", ce["properties"]["exitCode"])

# Comparison nested
cmp=load("docs/coop/design-corrections/workflows/schemas/evaluator3/comparison-result.schema.json")
for n in ["EvaluationContext","AuditProfile","EvidenceAvailability","Counts" if "Counts" in cmp["$defs"] else "Entry","Classification","PivotPresence"]:
    if n in cmp["$defs"]:
        print("\n====", n)
